            for (int i = 0; i < ncpnt; ++i)
            {
                row.push_back(_ctrlp[i]);

                if (((i + 1) % (_nknotU - _ordU)) == 0 && i != 0)
                {
                    vector<ControlPoint> new_ctrlp;
                    CalcControlPointsForAddingKnot(param, insert, _ordU, new_knot, row, new_ctrlp);
