            for (int i = 0; i < _ncpntU; ++i)
            {
                for (int j = 0; j < _ncpntV; ++j)
                {
                    row.push_back(_ctrlp[j * _ncpntU + i]);
                }

                vector<ControlPoint> new_ctrlp;
                CalcControlPointsForAddingKnot(param, insert, _ordV, new_knot, row, new_ctrlp);
