    else
    {
        for (int i = first_empty - 1; i >= 0; i--)
        {
            if (strcmp(symbol_table[i].kind, "CLASS") == 0 && strcmp(symbol_table[i].function, "DECLARATION") == 0 && strcmp(symbol_table[i].name, name) == 0)
