int			check_str_for_color(char *str)
{
	int count;
	int word;

	word = 0;
	str++;
	while (word < 3 && *str)
	{
		count = 0;
		while (*str == ' ')
			str++;
		while (*str >= '0' && *str <= '9')
		{
			count++;
			if (count > 3)
				file_exit(3);
			str++;
		}
		if (*str == ',')
			str++;
		if (*str == ',')
			file_exit(3);
		word++;
	}
	return (word);
}

