	for key, reading := range full.Readings {
		metaIDs = append(metaIDs, reading.MetaRecordID)
		data[key] = reading.Value
	}

	return &DataRow{
		ID:       full.ID,
		Time:     full.Time,
		Location: full.Location,
		MetaIDs:  unique(metaIDs),
		D:        data,
	}
}

