func main() {
	var concurrency int
	var parameters string
	var domains string
	var domain string
	var appendF bool
	flag.IntVar(&concurrency, "c", 30, "The concurrency for speed")
	flag.StringVar(&domains, "dL", "", "The domains file")
	flag.StringVar(&domain, "d", "", "The domain")
	flag.StringVar(&parameters, "p", "", "The parameters to gen wordlist")
	flag.BoolVar(&appendF, "a", true, "Append / at the end of the endpoint")
	flag.Parse()

	if (parameters != "" && domains != "") || (parameters != "" && domain != "") {
		var wg sync.WaitGroup
		for i := 0; i <= concurrency; i++ {
			wg.Add(1)
			go func() {
				gen(domains, domain,parameters, appendF)
				wg.Done()
			}()
			wg.Wait()
		}
	}
}

func gen(ds string, d string, p string, a bool) {

	// Regex to find relative links
	REGEX := `(https?|ftp|file)://[-A-Za-z0-9\+&@#/%?=~_|!:,.;]*[-A-Za-z0-9\+&@#/%=~_|]`

	time.Sleep(time.Millisecond * 10)

	var parameters = make([]string, 0)
	var links = make([]string, 0)
	var domains = make([]string, 0)

	client:=&http.Client{}

	jScanner := bufio.NewScanner(os.Stdin)
	for jScanner.Scan() {
		req, err := http.NewRequest("GET",jScanner.Text(), nil)
		if err != nil { return }
		resp,err := client.Do(req)
		if err != nil { return }
		bodyBytes,err := ioutil.ReadAll(resp.Body)
		if err != nil {
			return
		}

		bodyString := string(bodyBytes)
		re := regexp.MustCompile(REGEX)
		match := re.FindStringSubmatch(bodyString)
		if match != nil {
			links = append(links, string(match[0]))
		}
	}

	fp, err := os.Open(p)
	if err != nil {
		return
	}

	if d == "" {

		dp, err := os.Open(ds)
		if err != nil {
			return
		}

		dScanner := bufio.NewScanner(dp)
		for dScanner.Scan() {
			domains=append(domains, dScanner.Text())
		}

		pScanner := bufio.NewScanner(fp)
		for pScanner.Scan() {
			parameters = append(parameters, pScanner.Text())
		}

		for _,domain := range domains {
			for  _,link := range links {
				for _,parameter := range parameters {
					u, err := url.Parse(link)
					if err != nil {
						return
					}
					if a == false {
						fmt.Printf("%s%s?%s=FUZZ\n", domain, u.Path, parameter)
					}else {
						fmt.Printf("%s%s/?%s=FUZZ\n", domain, u.Path, parameter)
					}
				}
			}
		}
	}else {

		pScanner := bufio.NewScanner(fp)
                for pScanner.Scan() {
                        parameters = append(parameters, pScanner.Text())

	}
		}
	}
}

func (s *shellSocket) sendKernelInfo(req *message) error {
	return s.iopub.WithOngoingContext(func(_ context.Context) error {
		var info KernelInfo
		info = s.handlers.HandleKernelInfo()
		res := newMessageWithParent(req)

		// https://github.com/jupyter/notebook/blob/master/notebook/services/kernels/handlers.py#L174
		res.Header.MsgType = "kernel_info_reply"
		res.Content = &info
		return res.Send(s.socket, s.hmacKey)
	}, req)
}

func (s *shellSocket) handleMessages() error {
	msgs, err := s.socket.RecvMessageBytes(0)
	if err != nil {
		return fmt.Errorf("Failed to receive data from %s: %v", s.name, err)
	}
	var msg message
	err = msg.Unmarshal(msgs, s.hmacKey)
	if err != nil {
		return fmt.Errorf("Failed to unmarshal messages from %s: %v", s.name, err)
	}
	log.Debugf("MsgType in %s: %q", s.name, msg.Header.MsgType)
	switch typ := msg.Header.MsgType; typ {
	case "kernel_info_request":
		if err := s.sendKernelInfo(&msg); err != nil {
			log.Errorf("Failed to handle kernel_info_request: %v", err)
		}
	case "shutdown_request":
		log.Info("received shutdown_request.")
		s.cancelCtx()
		// TODO: Send shutdown_reply
	case "execute_request":
		s.execQueue.push(&msg, s)
	case "complete_request":
		go func() {
			reply := s.handlers.HandleComplete(msg.Content.(*CompleteRequest))
			if reply == nil {
				reply = &CompleteReply{
					Status: "ok",
				}
			}
			if reply.Status == "ok" && reply.Matches == nil {
				// matches must not be null because `jupyter console` can not accept null for matches as of 2017/12.
				// https://goo.gl/QRd5rG
				reply.Matches = make([]string, 0)
			}
			res := newMessageWithParent(&msg)
			res.Header.MsgType = "complete_reply"
			res.Content = reply
			s.pushResult(res)
		}()
	case "inspect_request":
		go func() {
			reply := s.handlers.HandleInspect(msg.Content.(*InspectRequest))
			if reply == nil {
				reply = &InspectReply{
					Status: "ok",
					Found:  false,
				}
			}
			res := newMessageWithParent(&msg)
			res.Header.MsgType = "inspect_reply"
			res.Content = reply
			s.pushResult(res)
		}()
	case "is_complete_request":
		go func() {
			reply := s.handlers.HandleIsComplete(msg.Content.(*IsCompleteRequest))
			if reply == nil {
				reply = &IsCompleteReply{Status: "unknown"}
			}
			res := newMessageWithParent(&msg)
			res.Header.MsgType = "is_complete_reply"
			res.Content = reply
			s.pushResult(res)
		}()
	default:
		log.Warningf("Unsupported MsgType in %s: %q", s.name, typ)
	}
	return nil
}

// Forward a message on result_pull to socket.
func (s *shellSocket) handleResultPull() error {
	msgs, err := s.resultPull.RecvMessageBytes(0)
	if err != nil {
		return err
	}
	if len(msgs) == 1 && string(msgs[0]) == "END_OF_LOOP" {
		return errLoopEnd
	}
	// For some reasons, execute_reply is not handled correctly
	// unless we unmarshal and marshal msgs rather than just forwarding them.
	var msg message
	if err := msg.Unmarshal(msgs, s.hmacKey); err != nil {
		return err
	}
	return msg.Send(s.socket, s.hmacKey)
}

