func goOperate(wg *sync.WaitGroup,tcpClient *tcp.TcpClient,c *fastcdc.Chunk,errorChan chan error){
	cmd := tcp.Cmd{Name: "PUT", Hash: c.Hash, Size: int64(c.Length), Data: c.Data, Error: nil}
