	}
	if cmd.Error != nil{
		errorChan <- cmd.Error
	}
	wg.Done()
}

func SendData(wg *sync.WaitGroup, chunksChan chan fastcdc.Chunk, errorChan chan error) {

	conn, e := net.Dial("tcp", "127.0.0.1:8080")
